class Solution:
    def findMirror(self, root, target):
        def dfs(node, target, level, parent):
            if not node:
                return None, None, None

            if node.data == target:
                return node, level, parent

            left_node, left_level, left_parent = dfs(node.left, target, level + 1, node)
            if left_node:
                return left_node, left_level, left_parent

            right_node, right_level, right_parent = dfs(node.right, target, level + 1, node)
            if right_node:
                return right_node, right_level, right_parent

            return None, None, None

        target_node, target_level, target_parent = dfs(root, target, 0, None)
        if not target_node:
            return -1

        def find_mirror(node, level, target_level, target_parent):
            if not node or level > target_level:
                return -1

            if node == target_parent:
                if target_node == target_parent.left:
                    return node.right.data if node.right else -1
                else:
                    return node.left.data if node.left else -1

            left_result = find_mirror(node.left, level + 1, target_level, target_parent)
            if left_result != -1:
                return left_result

            return find_mirror(node.right, level + 1, target_level, target_parent)

        return find_mirror(root, 0, target_level, target_parent)
